package io.fireflysoftware.domain.organization.core.owner;
import io.fireflysoftware.domain.organization.core.owner.impl.*;import org.fireflyframework.core.transaction.R2dbcOperationBudget;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.springframework.security.oauth2.client.*;import org.springframework.security.oauth2.client.registration.*;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.web.reactive.function.client.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import reactor.core.publisher.Mono;import java.time.*;import java.net.URI;import java.util.*;import java.util.concurrent.atomic.*;
class SdkCurrentBankOwnerSourceTest{
 static final Instant NOW=Instant.parse("2026-10-27T12:00:00Z");final UUID tenant=UUID.randomUUID(),bank=UUID.randomUUID(),id=UUID.randomUUID(),institution=UUID.randomUUID(),issuer=UUID.randomUUID();final CurrentBankOwnerQuery query=new CurrentBankOwnerQuery(tenant,bank,id,1);final java.time.Clock clock=Clock.fixed(NOW,ZoneOffset.UTC);final java.util.function.LongSupplier nanos=()->0L;Instant accessUntil=NOW.plusSeconds(4);final AtomicInteger requests=new AtomicInteger(),tokens=new AtomicInteger();
 BankOwnerMachineRegistration profile(){return new BankOwnerMachineRegistration(tenant,bank,"org-owner",URI.create("https://core.invalid"),URI.create("https://issuer.invalid/token"),URI.create("https://issuer.invalid/jwks"),"https://issuer.invalid","org-owner","domain-org-owner","domain-org",tenant.toString());}
 ClientRegistration registration(){return ClientRegistration.withRegistrationId("org-owner").clientId("domain-org").clientSecret("synthetic-source-unit-only").authorizationGrantType(AuthorizationGrantType.CLIENT_CREDENTIALS).tokenUri("https://issuer.invalid/token").build();}
 Jwt jwt(Map<String,Object> extra){var c=new HashMap<String,Object>(Map.of("iss","https://issuer.invalid","sub","domain-org-owner","aud",List.of("org-owner"),"tenant_id",tenant.toString(),"client_id","domain-org","principal_kind","MACHINE","exp",NOW.plusSeconds(4),"iat",NOW));c.putAll(extra);return new Jwt("source-unit-token",NOW,(Instant)c.get("exp"),Map.of("alg","RS256"),c);}
 String body(){var d=new HashMap<String,Object>();d.put("schemaVersion",1);d.put("readKind","CURRENT");d.put("tenantId",tenant);d.put("bankId",bank);d.put("enrollmentId",id);d.put("enrollmentVersion",1);d.put("institutionId",institution);d.put("issuerAuthorityId",issuer);d.put("allowedUses",List.of("ACCOUNTING_BOOK"));d.put("control",Map.of("state","ACTIVE","controlVersion",1));d.put("localCurrent",Map.of("ownershipGeneration",1,"bankGeneration",1,"sourceGeneration",1));d.put("currentUntilEpochMillis",NOW.plusSeconds(3).toEpochMilli());try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(d);}catch(Exception e){throw new RuntimeException(e);}}
 SdkCurrentBankOwnerSource source(Jwt jwt,HttpStatus status,String body,boolean cache){var reg=registration();ReactiveOAuth2AuthorizedClientManager manager=r->{tokens.incrementAndGet();return Mono.just(new OAuth2AuthorizedClient(reg,"machine",new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER,"source-unit-token",NOW,accessUntil)));};var web=WebClient.builder().exchangeFunction(r->{requests.incrementAndGet();assertEquals("Bearer source-unit-token",r.headers().getFirst("Authorization"));assertEquals(HttpMethod.GET,r.method());var x=ClientResponse.create(status).header("Content-Type","application/json");if(cache)x.header("Cache-Control","no-store");return Mono.just(x.body(body).build());}).build();return new SdkCurrentBankOwnerSource(profile(),manager,k->Mono.just(reg),t->Mono.just(jwt),web,clock,nanos);}
 R2dbcOperationBudget budget(){return R2dbcOperationBudget.observed(NOW,NOW.plusSeconds(10),0,Duration.ofSeconds(10),clock,nanos);}
 void status(int n,Runnable call){assertEquals(n,assertThrows(ResponseStatusException.class,call::run).getStatusCode().value());}
 @Test void genuineCoreSdkMapsExactCurrentSummary(){var o=source(jwt(Map.of()),HttpStatus.OK,body(),true).read(query,budget()).block();assertTrue(o.view().matches(query));assertEquals(institution,o.view().institutionId());assertEquals(1,requests.get());assertEquals(1,tokens.get());assertTrue(o.window().remaining().compareTo(Duration.ofSeconds(4))<=0);}
 @Test void wrongConfiguredBankStopsBeforeCredential(){status(403,()->source(jwt(Map.of()),HttpStatus.OK,body(),true).read(new CurrentBankOwnerQuery(tenant,UUID.randomUUID(),id,1),budget()).block());assertEquals(0,tokens.get());assertEquals(0,requests.get());}
 @Test void wrongSignedMachineSubjectStopsBeforeCore(){status(503,()->source(jwt(Map.of("sub","other")),HttpStatus.OK,body(),true).read(query,budget()).block());assertEquals(0,requests.get());}
 @Test void staffTokenCannotBecomeMachineCredential(){status(503,()->source(jwt(Map.of("staff_actor_id",UUID.randomUUID().toString())),HttpStatus.OK,body(),true).read(query,budget()).block());assertEquals(0,requests.get());}
 @Test void cacheableNativeBodyCannotBecomeCurrentObservation(){status(503,()->source(jwt(Map.of()),HttpStatus.OK,body(),false).read(query,budget()).block());}
 @Test void exactSuspensionIsConflict(){status(409,()->source(jwt(Map.of()),HttpStatus.CONFLICT,"{}",true).read(query,budget()).block());}
 @Test void upstreamPolicyDenialIsDependencyUnavailable(){status(503,()->source(jwt(Map.of()),HttpStatus.FORBIDDEN,"{}",true).read(query,budget()).block());}
 @Test void wrongNativeScopeIsUnavailable(){status(503,()->source(jwt(Map.of()),HttpStatus.OK,body().replace(id.toString(),UUID.randomUUID().toString()),true).read(query,budget()).block());}
 @Test void responseHandoffRetainsEarlierVerifiedMachineExpiry(){var o=source(jwt(Map.of("exp",NOW.plusSeconds(2))),HttpStatus.OK,body(),true).read(query,budget()).block();assertEquals(NOW.plusSeconds(3).toEpochMilli(),o.view().currentUntilEpochMillis());assertTrue(o.view().observationUntilEpochMillis()<=NOW.plusSeconds(2).toEpochMilli());}
 @Test void longerValidIssuerAndNativeLifetimesOnlyNarrowToOriginalBudget(){accessUntil=NOW.plusSeconds(120);var body=body().replace(Long.toString(NOW.plusSeconds(3).toEpochMilli()),Long.toString(NOW.plusSeconds(20).toEpochMilli()));var o=source(jwt(Map.of("exp",NOW.plusSeconds(120))),HttpStatus.OK,body,true).read(query,budget()).block();assertEquals(NOW.plusSeconds(20).toEpochMilli(),o.view().currentUntilEpochMillis());assertTrue(o.view().observationUntilEpochMillis()<=NOW.plusSeconds(10).toEpochMilli());assertTrue(o.window().remaining().compareTo(Duration.ofSeconds(10))<=0);}

 @Test void actualInitialEnrollmentZeroControlIsPreservedByGenuineSdk(){var o=source(jwt(Map.of()),HttpStatus.OK,body().replace("\"controlVersion\":1","\"controlVersion\":0"),true).read(query,budget()).block();assertEquals(0,o.view().controlVersion());assertTrue(o.view().matches(query));assertEquals(1,requests.get());}
 @Test void negativeControlVersionRemainsUnavailable(){status(503,()->source(jwt(Map.of()),HttpStatus.OK,body().replace("\"controlVersion\":1","\"controlVersion\":-1"),true).read(query,budget()).block());}
 @Test void zeroControlCopyPreservesScopeAndEarlierWindow(){var v=new CurrentBankOwnerView(tenant,bank,id,1,institution,issuer,Set.of("ACCOUNTING_BOOK"),0,1,2,2,NOW.plusSeconds(3).toEpochMilli(),NOW.plusSeconds(2).toEpochMilli());assertEquals(0,v.withObservationUntil(NOW.plusSeconds(1).toEpochMilli()).controlVersion());assertThrows(IllegalArgumentException.class,()->new CurrentBankOwnerView(tenant,bank,id,0,institution,issuer,Set.of("ACCOUNTING_BOOK"),0,1,2,2,NOW.plusSeconds(3).toEpochMilli(),NOW.plusSeconds(2).toEpochMilli()));}
}
